if(empty($_SESSION['UserName'])){$_SESSION['error']='Silakan login terlebih dahulu!';header('Location: /gg_app/login.php');exit;}
require '../../koneksi.php'; require '../../koneksi3.php'; include '../../includes/header.php'; include '../../includes/sidebar.php'; date_default_timezone_set('Asia/Jakarta');
$number=trim($_GET['ppnmbr']??''); $org=isset($_GET['org'])?(int)$_GET['org']:0; $status=($_GET['status']??'O')==='V'?'V':'O'; $header=null; $details=[];
$groupId=$_SESSION['GroupId']??0; $permStmt=sqlsrv_query($conn,'SELECT TOP 1 CanEdit FROM dbo.SMGroupTrustee WHERE GroupId=? AND MenuId=?',[$groupId,34]); $permissions=$permStmt ? sqlsrv_fetch_array($permStmt,SQLSRV_FETCH_ASSOC) : []; $canApprove=!empty($permissions['CanEdit']);
if($number!==''){
 $q='SELECT h.ppnmbr,h.ppdate,h.createdby,h.ppdesc,h.fgstatus,h.approveby,h.approvedate,o.prorgname,h.ppprorgid,o.prorgid FROM prpphd h INNER JOIN prprorg o ON h.ppprorgid=o.prorgid WHERE h.ppnmbr=:number';
 $s=$conn3->prepare($q);$s->execute([':number'=>$number]);$header=$s->fetch(PDO::FETCH_ASSOC);
 if($header){$d='SELECT h.ppnmbr,d.ppprodcode,d.ppprodname,u.uomname,d.ppuomid,d.ppstdqty,d.ppqty,d.ppproddesc,d.upduser,d.upddate FROM prpphd h INNER JOIN prprorg o ON h.ppprorgid=o.prorgid INNER JOIN prppdt d ON h.pphdid=d.pphdid INNER JOIN smuom u ON d.ppstduomid=u.uomid AND d.ppuomid=u.uomid WHERE h.ppnmbr=:number ORDER BY d.ppprodcode';$ds=$conn3->prepare($d);$ds->execute([':number'=>$number]);$details=$ds->fetchAll(PDO::FETCH_ASSOC);}
}
