?>
<div class="content-wrapper"><section class="content-header"><div class="container-fluid"><h1>Purchase Request</h1></div></section><section class="content"><div class="container-fluid"><?php if(!$header): ?><div class="alert alert-danger">Data PR tidak ditemukan.</div><?php else: ?><div class="card"><div class="card-header"><h3 class="card-title">Informasi Purchase Request: <?= $e($header['ppnmbr']) ?></h3></div><div class="card-body"><div class="row"><div class="col-md-6"><table class="table table-bordered"><tr><th style="width:35%">No PR</th><td><?= $e($header['ppnmbr']) ?></td></tr><tr><th>Date</th><td><?= $header['ppdate']?date('d/m/Y',strtotime($header['ppdate'])):'-' ?></td></tr><tr><th>PR Organization</th><td><?= $e($header['prorgname']) ?></td></tr><tr><th>Requested by Name</th><td><?= $e($header['createdby']) ?></td></tr></table></div><div class="col-md-6"><table class="table table-bordered"><tr><th style="width:35%">Description</th><td><?= nl2br($e($header['ppdesc'])) ?></td></tr><tr><th>Status</th><td><span class="badge badge-<?= $header['fgstatus']==='O'?'warning':'success' ?>"><?= $header['fgstatus']==='O'?'Open':'Approve' ?></span></td></tr><tr><th>Approve by</th><td><?= $e($header['approveby']??'-') ?></td></tr><tr><th>Approved date</th><td><?= !empty($header['approvedate'])?date('d/m/Y H:i',strtotime($header['approvedate'])):'-' ?></td></tr></table></div></div></div></div>
<div class="card"><div class="card-header"><h3 class="card-title">Detail Items</h3></div><div class="card-body table-responsive"><table class="table table-bordered table-hover table-sm"><thead class="thead-light"><tr><th>No</th><th>Product Code</th><th>Product Name</th><th>UOM</th><th>Standard Qty</th><th>Qty</th><th>Description</th><th>Updated By</th><th>Updated Date</th></tr></thead><tbody><?php foreach($details as $i=>$d): ?><tr><td><?= $i+1 ?></td><td><?= $e($d['ppprodcode']) ?></td><td><?= $e($d['ppprodname']) ?></td><td><?= $e($d['uomname']) ?></td><td class="text-right"><?= number_format((float)$d['ppstdqty'],2) ?></td><td class="text-right"><?= number_format((float)$d['ppqty'],2) ?></td><td><?= $e($d['ppproddesc']) ?></td><td><?= $e($d['upduser']) ?></td><td><?= !empty($d['upddate'])?date('d/m/Y H:i',strtotime($d['upddate'])):'-' ?></td></tr><?php endforeach ?><?php if(!$details): ?><tr><td colspan="9" class="text-center">Tidak ada detail item.</td></tr><?php endif ?></tbody></table></div><div class="card-footer d-flex justify-content-center" style="gap:10px"><?php if($canApprove && $header['fgstatus']==='O'): ?><button type="button" class="btn btn-success" id="pr-view-approve" data-ppnmbr="<?= $e($header['ppnmbr']) ?>"><i class="fas fa-check-circle"></i> Approve</button><?php endif ?> <a class="btn btn-secondary" href="pr_approve.php?org=<?= $org?: (int)$header['prorgid'] ?>&status=<?= $status ?>"><i class="fas fa-arrow-left"></i> Kembali</a></div></div><?php endif ?></div></section></div><?php include '../../includes/footer.php'; ?>
<?php if($header && $canApprove && $header['fgstatus']==='O'): ?><script src="/gg_app/plugins/AdminLTE-3.2.0/plugins/sweetalert2/sweetalert2.all.min.js"></script><script>$(function(){ $('#pr-view-approve').on('click',function(){const button=$(this);Swal.fire({title:'Approve PR ini?',icon:'question',showCancelButton:true,confirmButtonText:'Ya, approve'}).then(function(result){if(!result.isConfirmed)return;button.prop('disabled',true);$.post('proses_approve.php',{action:'approve',ppnmbrs:[button.data('ppnmbr')]},function(res){if(res.status==='success'){location.href='view_order.php?ppnmbr='+encodeURIComponent(button.data('ppnmbr'))+'&org=<?= $org ?>'+'&status=O';}else{button.prop('disabled',false);Swal.fire('Gagal',res.message||'PR gagal di-approve.','error')}},'json').fail(function(x){button.prop('disabled',false);Swal.fire('Gagal',x.responseJSON?.message||'Permintaan gagal diproses.','error')})})});});</script><?php endif ?>
